        a0,a1,a2,a3=p[0:4]
        cf=p[4:4+Bp.shape[1]]; ct=p[4+Bp.shape[1]:4+2*Bp.shape[1]]
        Fp=Bp@cf; Ft=Bt@ct
        taus=np.exp(Ft)
        lp=a0+a1*np.log(Ef)+a2*np.log(L)+a3*np.log(dT)+Fp
        if laplace=='st_over':
            return lp+np.log(s)-np.log(s+taus)
        elif laplace=='inv':
            return lp-np.log(1+s*taus)
        elif laplace=='none':
            return lp
    def resid(p):
        return model(p)-ly
